import 'package:flutter/material.dart';
import '../../theme/app_theme.dart';

/// The Wordnook brand mark — the "lamp-lit nook" app icon — shared by the
/// About screen and the menu-drawer header, sized by [size]. Same artwork as
/// the launcher icon (generated by tools/brand/generate_icons.py).
class AppMark extends StatelessWidget {
  final double size;
  const AppMark({super.key, required this.size});

  static const String asset = 'assets/brand/app_icon.png';

  @override
  Widget build(BuildContext context) {
    return Container(
      width: size,
      height: size,
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(size * 0.24),
        border: Border.all(color: AppPalette.coinPillBorder),
        boxShadow: const [
          BoxShadow(
              color: Color(0x40000000), blurRadius: 18, offset: Offset(0, 8)),
        ],
      ),
      child: ClipRRect(
        borderRadius: BorderRadius.circular(size * 0.24),
        child: Image.asset(
          asset,
          width: size,
          height: size,
          fit: BoxFit.cover,
          semanticLabel: 'Wordnook',
          filterQuality: FilterQuality.medium,
        ),
      ),
    );
  }
}
